INSERT INTO ropa.activity_templates (template_set_id, code, name_th, name_en, job_category, role, defaults, rationale, legal_refs) VALUES
        ('00000000-0000-7000-8000-000000000011', 'retail_pos_transaction', 'บันทึกรายการขายหน้าร้าน (POS)', 'Point-of-sale transaction recording', 'pos_transaction', 'controller', '{"description_th": "บันทึกรายการซื้อขายสินค้าและการชำระเงินของลูกค้าที่หน้าร้าน", "description_en": "Record customer purchase transactions and payments at the point of sale", "purposes": [{"purpose_text_th": "ให้บริการขายและปฏิบัติตามสัญญาซื้อขาย", "purpose_text_en": "Providing retail sales and performing the sale contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "customer", "source": "direct"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ให้บริการระบบชำระเงิน (payment gateway)"}], "retention": [{"retention_months": 84, "retention_basis_th": "เก็บตามข้อกำหนดบัญชีและภาษี", "trigger_event_th": "วันที่สิ้นรอบบัญชีที่เกี่ยวข้อง", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"บันทึกรายการขายหน้าร้าน (POS)\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000011', 'retail_loyalty_program', 'สมาชิกบัตรสะสมแต้มและสิทธิพิเศษ', 'Loyalty program membership', 'loyalty_program', 'controller', '{"description_th": "เก็บข้อมูลสมาชิกเพื่อสะสมแต้มและส่งสิทธิพิเศษทางการตลาด", "description_en": "Collect member data to accrue points and send marketing offers", "purposes": [{"purpose_text_th": "บริหารโปรแกรมสมาชิกและสื่อสารการตลาด", "purpose_text_en": "Managing the loyalty program and marketing communications", "lawful_basis_code": "CONSENT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "online_identifier", "subject_type_code": "customer", "source": "indirect"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ให้บริการระบบบริหารโปรแกรมสมาชิกภายนอก"}], "retention": [{"retention_months": 36, "retention_basis_th": "เก็บระหว่างสถานะสมาชิกยังใช้งานอยู่", "trigger_event_th": "วันที่ยกเลิกสมาชิกภาพหรือไม่มีการใช้งานตามรอบที่กำหนด", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"สมาชิกบัตรสะสมแต้มและสิทธิพิเศษ\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000012', 'hospital_patient_medical_record', 'จัดทำและเก็บเวชระเบียนผู้ป่วย', 'Patient medical record keeping', 'patient_care', 'controller', '{"description_th": "บันทึกประวัติการรักษาและข้อมูลสุขภาพของผู้ป่วยเพื่อการวินิจฉัยและรักษา", "description_en": "Record treatment history and health data for diagnosis and care", "purposes": [{"purpose_text_th": "ให้บริการรักษาพยาบาลตามสัญญาการให้บริการ", "purpose_text_en": "Providing medical treatment under the service contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "health", "subject_type_code": "customer", "source": "direct"}], "recipients": [], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามมาตรฐานเวชระเบียนสถานพยาบาล", "trigger_event_th": "ครบรอบการทบทวนเวชระเบียนตามนโยบายสถานพยาบาล", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"จัดทำและเก็บเวชระเบียนผู้ป่วย\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000012', 'hospital_billing_insurance_claim', 'เรียกเก็บค่ารักษาและเบิกเคลมประกัน', 'Billing and insurance claims processing', 'billing_insurance', 'controller', '{"description_th": "ประมวลผลข้อมูลค่าใช้จ่ายและข้อมูลสุขภาพที่จำเป็นเพื่อเบิกเคลมกับบริษัทประกัน", "description_en": "Process billing and necessary health data to file insurance claims", "purposes": [{"purpose_text_th": "เรียกเก็บค่ารักษาและดำเนินการเบิกเคลมตามสัญญา", "purpose_text_en": "Billing and processing insurance claims under contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "health", "subject_type_code": "customer", "source": "indirect"}], "recipients": [{"recipient_role": "controller", "note_th": "บริษัทประกันภัยผู้รับเคลม"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามระยะเวลาการเก็บเอกสารทางบัญชีและเวชระเบียน", "trigger_event_th": "ครบรอบการทบทวนเอกสารเบิกจ่ายประจำปี", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"เรียกเก็บค่ารักษาและเบิกเคลมประกัน\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)','ม.39(5)']),
        ('00000000-0000-7000-8000-000000000013', 'finance_kyc_onboarding', 'ตรวจสอบและยืนยันตัวตนลูกค้า (KYC)', 'Know-your-customer onboarding', 'kyc_onboarding', 'controller', '{"description_th": "เก็บและตรวจสอบเอกสารแสดงตนของลูกค้าก่อนเปิดบัญชีหรือทำธุรกรรมทางการเงิน", "description_en": "Collect and verify identity documents before opening an account or financial transaction", "purposes": [{"purpose_text_th": "ปฏิบัติตามกฎหมายป้องกันการฟอกเงินและรู้จักลูกค้า", "purpose_text_en": "Compliance with anti-money-laundering and KYC law", "lawful_basis_code": "LEGAL_OBLIGATION"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "national_id", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "customer", "source": "direct"}], "recipients": [{"recipient_role": "controller", "note_th": "หน่วยงานกำกับดูแลภาคการเงิน"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามข้อกำหนดกฎหมายป้องกันการฟอกเงิน", "trigger_event_th": "วันที่ปิดบัญชีหรือสิ้นสุดความสัมพันธ์ทางธุรกิจ", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"ตรวจสอบและยืนยันตัวตนลูกค้า (KYC)\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000013', 'finance_insurance_claims_processing', 'ประมวลผลคำขอเคลมสินไหมประกันภัย', 'Insurance claims processing', 'claims_processing', 'controller', '{"description_th": "ตรวจสอบและประมวลผลคำขอรับสินไหมทดแทนตามกรมธรรม์ของผู้เอาประกัน", "description_en": "Verify and process indemnity claims under the policyholder''s contract", "purposes": [{"purpose_text_th": "ปฏิบัติตามสัญญากรมธรรม์ประกันภัย", "purpose_text_en": "Performing the insurance policy contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "customer", "source": "direct"}, {"data_category_code": "health", "subject_type_code": "customer", "source": "direct"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ประเมินความเสียหาย/แพทย์ที่ปรึกษาภายนอก"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามข้อกำหนดคุ้มครองผู้บริโภคด้านประกันภัย", "trigger_event_th": "วันที่สิ้นสุดกรมธรรม์หรือปิดคดีเคลม", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"ประมวลผลคำขอเคลมสินไหมประกันภัย\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)','ม.39(5)']),
